package counter

import "unicode"

// counter implements Counter, counting the number of lines, letters
// and total characters across all strings added via AddString.
type counter struct {
	newlines int
	chars    int
	letters  int
	lastChar rune
}

// NewCounter returns a new Counter.
func NewCounter() Counter {
	return &counter{}
}

// AddString adds the counts for s to the counter.
func (c *counter) AddString(s string) {
	for _, char := range s {
		c.lastChar = char
		if char == '\n' {
			c.newlines++
		} else if unicode.IsLetter(char) {
			c.letters++
		}
		c.chars++
	}
}

// Lines reports the number of lines. A trailing line without a
// terminating newline is counted as a line.
func (c *counter) Lines() int {
	switch {
	case c.chars == 0:
		return 0
	case c.lastChar == '\n':
		return c.newlines
	default:
		return c.newlines + 1
	}
}

// Letters reports the number of letters.
func (c *counter) Letters() int { return c.letters }

// Characters reports the total number of characters.
func (c *counter) Characters() int { return c.chars }
